[{'content': 'Phát triển một chương trình Python đọc tất cả các tệp văn bản trong một thư mục và trả về 5 từ xuất hiện nhiều nhất.', 'role': 'user'}, {'content': '```python
import os
from collections import Counter
import re

def lay_5_tu_xuat_hien_nhieu_nhat(thu_muc):
    """
    Đọc toàn bộ tệp văn bản (.txt) trong `thu_muc`,
    đếm tần suất từ và trả về 5 từ xuất hiện nhiều nhất.
    """
    bo_dem = Counter()

    # Duyệt qua từng tệp trong thư mục
    for ten_tep in os.listdir(thu_muc):
        duong_dan = os.path.join(thu_muc, ten_tep)

        # Chỉ xử lý tệp có phần mở rộng .txt
        if not os.path.isfile(duong_dan) or not ten_tep.lower().endswith('.txt'):
            continue

        try:
            with open(duong_dan, 'r', encoding='utf-8') as f:
                noi_dung = f.read().lower()

                # Loại bỏ ký tự không phải chữ và tách thành từ
                tu_danh_sach = re.findall(r'\b\w+\b', noi_dung)
                bo_dem.update(tu_danh_sach)
        except Exception as e:
            print(f"Lỗi khi đọc tệp {ten_tep}: {e}")

    # Lấy 5 từ phổ biến nhất
    nam_tu_hang_dau = bo_dem.most_common(5)
    return nam_tu_hang_dau


if __name__ == "__main__":
    thu_muc_can_quet = input("Nhập đường dẫn thư mục chứa tệp văn bản: ").strip()
    ket_qua = lay_5_tu_xuat_hien_nhieu_nhat(thu_muc_can_quet)

    if ket_qua:
        print("\nTop 5 từ xuất hiện nhiều nhất:")
        for tu, so_lan in ket_qua:
            print(f"{tu}: {so_lan}")
    else:
        print("Không tìm thấy tệp .txt nào trong thư mục đã cho.")
```', 'role': 'assistant'}, {'content': 'Bạn có thể song song hóa nó được không?', 'role': 'user'}, {'content': 'Dưới đây là phiên bản song song hóa (parallel) bằng `concurrent.futures.ProcessPoolExecutor`.  
Mỗi tệp được xử lý trên một CPU riêng, sau đó gộp kết quả về Counter chính.

```python
import os
import re
from collections import Counter
from concurrent.futures import ProcessPoolExecutor, as_completed

def dem_tu_trong_tep(duong_dan):
    """Đọc 1 tệp và trả về Counter từ."""
    try:
        with open(duong_dan, 'r', encoding='utf-8') as f:
            noi_dung = f.read().lower()
        tu_danh_sach = re.findall(r'\b\w+\b', noi_dung)
        return Counter(tu_danh_sach)
    except Exception as e:
        # Trả về Counter rỗng nếu lỗi
        print(f"Lỗi khi đọc {duong_dan}: {e}")
        return Counter()

def lay_5_tu_xuat_hien_nhieu_nhat_song_song(thu_muc, so_luong_cpu=None):
    """Song song hóa việc đếm từ trên nhiều CPU."""
    danh_sach_txt = [
        os.path.join(thu_muc, ten)
        for ten in os.listdir(thu_muc)
        if os.path.isfile(os.path.join(thu_muc, ten)) and ten.lower().endswith('.txt')
    ]

    if not danh_sach_txt:
        return []

    # Gộp tất cả Counter
    tong_counter = Counter()
    with ProcessPoolExecutor(max_workers=so_luong_cpu) as executor:
        # Map từng tệp
        for future in as_completed(executor.submit(dem_tu_trong_tep, tep) for tep in danh_sach_txt):
            tong_counter.update(future.result())

    return tong_counter.most_common(5)

if __name__ == "__main__":
    thu_muc_can_quet = input("Nhập đường dẫn thư mục chứa tệp văn bản: ").strip()
    top5 = lay_5_tu_xuat_hien_nhieu_nhat_song_song(thu_muc_can_quet)
    if top5:
        print("\nTop 5 từ xuất hiện nhiều nhất:")
        for tu, so_lan in top5:
            print(f"{tu}: {so_lan}")
    else:
        print("Không tìm thấy tệp .txt nào trong thư mục đã cho.")
```', 'role': 'assistant'}]

